124: // Helper to generate GRN dynamically
125: async function generateGRN(conn, firm_id) {
126:   // 1. Fetch Firm Settings
127:   const [firms] = await conn.execute('SELECT settings FROM Firms WHERE id = ?', [firm_id]);
128:   const settings = firms[0]?.settings || {};
129:   const template = settings.grn_template || 'GRN-{{SEQ}}'; // default template
130: 
131:   // 2. Fetch the latest GRN sequence for this firm
132:   const [latest] = await conn.execute(
133:     'SELECT grn_no FROM PurchaseInvoices WHERE firm_id = ? ORDER BY id DESC LIMIT 1', 
134:     [firm_id]
135:   );
136:   
137:   let nextSeq = 1;
138:   if (latest.length > 0 && latest[0].grn_no) {
139:     // Extract the numeric part at the end of the GRN
140:     const match = latest[0].grn_no.match(/(\d+)$/);
141:     if (match) {
142:       nextSeq = parseInt(match[1], 10) + 1;
143:     }
144:   }
145: 
146:   const seqStr = String(nextSeq).padStart(4, '0');
147:   
148:   // Replace tokens
149:   let grn = template.replace('{{SEQ}}', seqStr);
150:   
151:   // Add more dynamic logic like FY, MM, DD if needed by the template
152:   const date = new Date();
153:   grn = grn.replace('{{YYYY}}', date.getFullYear());
154:   grn = grn.replace('{{MM}}', String(date.getMonth() + 1).padStart(2, '0'));
155:   grn = grn.replace('{{DD}}', String(date.getDate()).padStart(2, '0'));
156: 
157:   return grn;
158: }
