        below_rate: 5,
        above_rate: 18,
        flat_rate: 5 // used only if type is 'flat'
    };

    await db.execute('UPDATE Firms SET settings = ? WHERE id = 1', [JSON.stringify(settings)]);
    console.log('GST Rules successfully saved to Firm settings in the database.');
    process.exit(0);
}
