import os
import re
import subprocess

directory = "/Users/ratan/Downloads/RetailNodeV2/sample/invoices"

for filename in os.listdir(directory):
    if filename.endswith(".pdf"):
        filepath = os.path.join(directory, filename)
        result = subprocess.run(['pdftotext', '-layout', filepath, '-'], stdout=subprocess.PIPE, text=True)
        text = result.stdout

        # We look for "Rate" and "Mrp"
        lines = text.split('\n')
        for i, line in enumerate(lines):
            if 'Rate' in line:
                rates = [float(x) for x in re.findall(r'\b\d{4}\b', line) if float(x) > 500 and float(x) < 5000]
                if rates and i + 1 < len(lines) and 'Mrp' in lines[i+1]:
                    mrps = [float(x) for x in re.findall(r'\b\d{4}\b', lines[i+1])]

                    for rate in rates:
                        if rate < 2500:
                            for mrp in mrps:
                                if mrp > 2500:
                                    print(f"Found in {filename}: Rate={rate}, MRP={mrp}")
                                    break
